import{R as t,e as n,f as o,U as r}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"AWeber","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/aweber.md","filePath":"integrations/email-marketing/aweber.md","lastUpdated":1775908585000}'),i={name:"integrations/email-marketing/aweber.md"};function a(l,e,s,h,g,c){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="aweber" tabindex="-1">AWeber <a class="header-anchor" href="#aweber" aria-label="Permalink to &quot;AWeber&quot;">​</a></h1><p>Follow the below steps to connect to the AWeber API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select AWeber as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-aweber-api" tabindex="-1">Step 2. Connect to the AWeber API <a class="header-anchor" href="#step-2-connect-to-the-aweber-api" aria-label="Permalink to &quot;Step 2. Connect to the AWeber API&quot;">​</a></h3><ol><li>Go to <a href="https://labs.aweber.com/" target="_blank">AWeber Developer Center</a> and create a developer account.</li><li>In the top main menu, click on <strong>My Apps</strong>.</li><li>Click the <strong>Create A New App</strong> button.</li><li>Fill in the required fields. <ul><li>For <strong>Client Type</strong> select <strong>Confidential</strong>.</li></ul></li><li>In the <strong>OAuth Redirect URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from AWeber and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from AWeber and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to AWeber, where you must approve Formie to access your AWeber account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const b=t(i,[["render",a]]);export{p as __pageData,b as default};
